import pathlib,subprocess,json,hashlib,re,numpy as np,concurrent.futures
p=pathlib.Path('assets/incoming/audio_a11');requests=json.loads((p/'REQUESTS.json').read_text(encoding='utf8'));gen={x['key']:x for x in json.loads((p/'GENERATIONS.json').read_text(encoding='utf8'))};
