 g=gen[q['key']];x=decode(p/g['file']);pk=float(np.max(abs(x)));assert pk>1e-5,q['key'];h=np.flatnonzero(abs(x)>=max(pk*.012,1e-5));start=max(0,int(h[0])-441);end=min(len(x),int(h[-1])+1323);y=x[start:end].copy();limit=q['limit_ms'];maxn=round((limit-40)*44.1);tempo=1.;retained=1.
 if len(y)>maxn:
  if q['kind']=='voice':tempo=len(y)/maxn
  else:
   retained=float(np.sum(y[:maxn]**2)/max(1e-12,float(np.sum(y**2))));y=y[:maxn];fade=min(len(y),round(.012*44100));y[-fade:]*=np.linspace(1,0,fade)
